ruleContent.imageDecode:
var srcKey = (String(src).split('_key=')[1] || '').split('&')[0]
if (srcKey && result && result.length > 28) {
    try {
        var keyBytes = java.hexDecodeToByteArray(srcKey);

        // 提取加密数据各部分
        var iv = Packages.java.util.Arrays.copyOfRange(result, 0, 12);
        var ciphertextWithTag = Packages.java.util.Arrays.copyOfRange(result, 12, result.length);

        // 配置 AES-GCM 解密器
        var cipher = Packages.javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");
        var keySpec = new Packages.javax.crypto.spec.SecretKeySpec(keyBytes, "AES");
        var gcmParamSpec = new Packages.javax.crypto.spec.GCMParameterSpec(128, iv);

        // 解密
        cipher.init(2, keySpec, gcmParamSpec);
        var decryptedBytes = cipher.doFinal(ciphertextWithTag);
        java.log("解密成功，结果长度：" + decryptedBytes.length + " 字节");

        result = decryptedBytes;
    } catch (e) {
        java.log("解密失败！错误类型：" + e.javaException.getClass().getName());
        java.log("错误信息：" + e.message);
    }
} else {
    java.log("跳过解密：密钥不存在或数据长度不足");
}
result;

