ruleContent.content:
$.data.content
<js>
(function(){
    const isVideo = "{{$.data.tab}}" === "video";
    if(!isVideo) return result;
    try {
        const content = result
            .replace(/\\+/g, '')
            .replace(/\s+/g, ' ')
            .match(/https?:\/\/\S+/)[0];

        if(typeof book !== 'undefined' && 
           typeof chapter !== 'undefined' &&
           book.durChapterIndex === chapter.index) {
            const videoPlayerHTML = `
                <!DOCTYPE html>
                <html lang="zh">
                <head>
                    <meta charset="UTF-8">
                    <meta name="viewport" content="width=device-width, initial-scale=1.0">
                    <title>${chapter.title || '视频播放'}</title>
                    <style>
 *{margin:0;padding:0;box-sizing:border-box;}body{background:black;overflow:hidden;}
                    video{
                          position:fixed;
                          top:0;
                          left:0;
                          width:100%;
                          height:100%;
                          object-fit:contain;
                     }</style>
                </head>
                <body>
<video controls autoplay playsinline>
                        <source src="${content}" type="video/mp4">您的浏览器不支持HTML5视频</video></body></html>`;

            java.startBrowser(`data:text/html;charset=utf-8,${encodeURIComponent(videoPlayerHTML)}`, 
                            chapter.title || '视频播放');
            java.toast('视频加载中，请稍候...');
        }
        return `【📺刷新播放】视频地址：${content}`;
    } catch(e) {
        return result;
    }
})()
</js>

